"""Source-scoped trial cards; population comparisons are not individual predictions."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];F=R/'data/regimen-knowledge-base-v08433-addendum.json';K=json.loads(F.read_text());DATE='2026-11-04'
K['evidence_records']=[x for x in K['evidence_records'] if not x['evidence_id'].startswith('v08433-')]
def src(pmid,label):return {'label':label,'url':'https://pubmed.ncbi.nlm.nih.gov/'+pmid+'/'}
def endpoint(kind,label,a,b,unit,hr,ci,source,status,interpretation):
 d=dict(endpoint=kind,metric=label,intervention_value=a,comparator_value=b,unit=unit,interpretation=interpretation,analysis_status=status,sources=[source])
 if hr:d['hr']=str(hr)
 if ci:d['ci']=ci
 return d
S={
 '00555':[src('17470860','GONO phase III — Falcone et al., JCO 2007')],
 '00783':[src('25337750','TRIBE primary analysis — Loupakis et al., NEJM 2014'),src('26338525','TRIBE updated survival — Cremolini et al., Lancet Oncology 2015')],
 '00691':[src('33862000','PRODIGE 23 — Conroy et al., Lancet Oncology 2021')],
 '00238':[src('22949147','VELOUR — Van Cutsem et al., JCO 2012')],
 '00791':[src('25937430','TCOG-GI0802 — Sasaki et al., 2015')]
}
E={
 '00555':dict(trial='GONO phase III',population='244 patients with previously untreated, unresectable metastatic colorectal cancer; selected trial population aged 18–75.',comparison='FOLFOXIRI versus FOLFIRI',applicability='Direct comparison of the trial triplet and doublet. The response rate was the primary endpoint; survival measures are separate outcomes.',endpoints=[endpoint('PFS','Median progression-free survival',9.8,6.9,'months',.63,None,S['00555'][0],'2007 primary report','Progression-free survival improved; this is not an individual survival estimate.'),endpoint('OS','Median overall survival',22.6,16.7,'months',.70,None,S['00555'][0],'2007 primary report','Trial-group survival comparison; the median difference is not an expected extra lifetime for an individual.')],limitations=['Selected fit metastatic population; do not transfer these estimates to adjuvant or rectal neoadjuvant treatment.','Confidence intervals for these hazard ratios are not supplied in the accessible abstract; none are invented.'],harms='Grade 3–4 neutropenia occurred in 50% with FOLFOXIRI versus 28% with FOLFIRI; grade 2–3 neuropathy was 19% versus 0%.'),
 '00783':dict(trial='TRIBE',population='508 patients receiving first-line treatment for metastatic colorectal cancer.',comparison='FOLFOXIRI + bevacizumab versus FOLFIRI + bevacizumab',applicability='Both groups received bevacizumab. This comparison evaluates triplet versus doublet chemotherapy with bevacizumab; it cannot isolate the benefit of adding bevacizumab.',endpoints=[endpoint('PFS','Median progression-free survival',12.1,9.7,'months',.75,'0.62–0.90',S['00783'][0],'2014 primary report','PFS improved with the triplet; it is a distinct endpoint from overall survival.'),endpoint('OS','Updated median overall survival',29.8,25.8,'months',.80,'0.65–0.98',S['00783'][1],'2015 updated survival analysis','Updated survival results supersede the initial immature OS comparison.')],limitations=['First-line metastatic trial population; results do not apply to every patient or treatment setting.','The two arms both include bevacizumab.'],harms='The triplet increases treatment burden and clinically important toxicity, including neutropenia, diarrhoea, mucosal toxicity and neuropathy.'),
 '00691':dict(trial='UNICANCER-PRODIGE 23',population='461 patients with locally advanced cT3–4 M0 rectal adenocarcinoma, aged 18–75, WHO performance status 0–1.',comparison='Six FOLFIRINOX cycles → chemoradiotherapy → surgery → three months adjuvant chemotherapy versus chemoradiotherapy → surgery → six months adjuvant chemotherapy',applicability='The trial compared complete perioperative strategies. The result cannot be attributed to six induction cycles alone.',endpoints=[endpoint('DFS','Three-year disease-free survival',76,69,'%',.69,'0.49–0.97',S['00691'][0],'2021 primary report; median follow-up 46.5 months','DFS is not overall survival or an individual probability of cure.')],limitations=['Later surgery and adjuvant treatment were part of the intervention; an induction-only benefit is not estimated.','Patient selection and the complete multidisciplinary pathway matter.'],harms='During induction, grade 3–4 neutropenia occurred in 17% and diarrhoea in 11%; the later treatment phases have separate toxicities.'),
 '00238':dict(trial='VELOUR',population='1,226 patients with metastatic colorectal cancer previously treated with oxaliplatin; prior bevacizumab was permitted.',comparison='Aflibercept + FOLFIRI (612 patients) versus placebo + FOLFIRI (614 patients)',applicability='Second-line oxaliplatin-exposed metastatic population. The treatment comparison includes both the benefit and added toxicity of aflibercept.',endpoints=[endpoint('OS','Median overall survival',13.50,12.06,'months',.817,'0.713–0.937',S['00238'][0],'2012 primary report','The primary report uses a 95.34% confidence interval; the median difference is not an individual survival gain.'),endpoint('PFS','Median progression-free survival',6.90,4.67,'months',.758,'0.661–0.869',S['00238'][0],'2012 primary report','PFS is distinct from overall survival.')],limitations=['Do not apply these estimates to adjuvant disease or an unselected colorectal population.','Balance the population benefit against fitness, prior treatment and toxicity.'],harms='VEGF-inhibition risks include hypertension, proteinuria, bleeding, thrombosis and impaired wound healing, with additional chemotherapy-associated toxicity.'),
 '00791':dict(trial='TCOG-GI0802 / modified OPTIMOX-1 plus bevacizumab',population='First-line metastatic colorectal cancer in a single-arm phase II study.',comparison='No randomised comparator for the isolated bevacizumab/fluorouracil/folinic-acid segment',applicability='The study evaluated induction with bevacizumab/mFOLFOX6, a maintenance phase and later oxaliplatin reintroduction as one strategy.',qualitative_result='The source supports the treatment sequence; it does not quantify the comparative benefit of this maintenance segment by itself.',endpoints=[],limitations=['Do not assign the whole-strategy survival or response rates to isolated NCCP 00791.','NCCP v2 identifies bevacizumab in this regimen as unlicensed in Ireland; explain this and follow the local consent process.'],harms='Discuss fluoropyrimidine toxicity and the separate vascular, blood-pressure, renal-protein and wound-healing risks of bevacizumab.')
}
for k in K['regimen_profiles']:
 c=k['protocol_id'].split('-')[1]
 if c not in E:continue
 if c=='00783':k['source_reconciliation_supersedes']=['0.70.0']
 e=E[c];e.update(checked=DATE,sources=S[c]);
 if c=='00238':e['endpoints'][0]['confidence_level']=95.34
 k['evidence_at_a_glance']=e;k['evidence_audit']['remaining_uncertainties']=e['limitations']
 for x in e['endpoints']:
  x['intervention_label']={'00555':'FOLFOXIRI','00783':'FOLFOXIRI + bevacizumab','00691':'FOLFIRINOX perioperative strategy','00238':'Aflibercept + FOLFIRI'}[c]
  x['comparator_label']={'00555':'FOLFIRI','00783':'FOLFIRI + bevacizumab','00691':'Standard perioperative strategy','00238':'Placebo + FOLFIRI'}[c]
 for s in S[c]:
  if not any(q['url']==s['url'] for q in k['reference_links']):k['reference_links'].append(s)
 K['evidence_records'].append(dict(evidence_id='v08433-'+c,protocol_id=k['protocol_id'],nccp_regimen_code=c,trial_acronym=e['trial'],publication_title=S[c][0]['label'],publication_url=S[c][0]['url'],evidence_relationship='Regimen-specific source context',relevance_summary=e['applicability'],population=e['population'],review_status=K['governance'],source_checked_date=DATE,supporting_publications=S[c][1:]))
F.write_text(json.dumps(K,ensure_ascii=False,indent=2)+'\n');print('Five primary-study evidence cards integrated; no isolated-maintenance survival estimate assigned.')
